SELECT country, CASE WHEN rating >= 4.5 THEN 'high' WHEN rating >= 1.4 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT rating) AS unique_countrys, COUNT(DISTINCT rating) AS unique_citys FROM suppliers WHERE supplier_name LIKE '%Gmb%' GROUP BY country, CASE WHEN rating >= 4.5 THEN 'high' WHEN rating >= 1.4 THEN 'mid' ELSE 'low' END HAVING COUNT(DISTINCT rating) > 3 ORDER BY unique_citys DESC;
